package cn.huankan.collector;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.math.*;import java.util.*;
public final class SecXbrlParser {
 public record Fact(String cik,String taxonomy,String concept,String unit,LocalDate start,LocalDate end,BigDecimal value,String accession,String form,LocalDate filed,String fiscalPeriod,JsonNode raw){}
 public static List<Fact> parse(byte[] raw,Set<String> concepts){try{JsonNode root=new ObjectMapper().readTree(raw);String cik=root.path("cik").asText();if(!cik.matches("[0-9]{1,10}")||concepts.isEmpty()||concepts.size()>30)throw new IllegalArgumentException("CIK或事实目录无效");cik=String.format("%010d",Long.parseLong(cik));var result=new ArrayList<Fact>();var taxonomies=root.path("facts").fields();while(taxonomies.hasNext()){var t=taxonomies.next();var entries=t.getValue().fields();while(entries.hasNext()){var c=entries.next();if(!concepts.contains(c.getKey()))continue;var units=c.getValue().path("units").fields();while(units.hasNext()){var u=units.next();if(!Set.of("USD","shares","USD/shares","pure").contains(u.getKey()))throw new IllegalArgumentException("单位未明确支持，不能转换");for(var f:u.getValue()){String form=f.path("form").asText();if(!Set.of("10-K","10-Q","8-K","10-K/A","10-Q/A","8-K/A").contains(form))continue;String accession=f.path("accn").asText();if(!accession.matches("[0-9]{10}-[0-9]{2}-[0-9]{6}"))throw new IllegalArgumentException("accession格式无效");LocalDate start=f.hasNonNull("start")?LocalDate.parse(f.get("start").asText()):null,end=LocalDate.parse(f.path("end").asText()),filed=LocalDate.parse(f.path("filed").asText());if(start!=null&&start.isAfter(end)||filed.isBefore(end))throw new IllegalArgumentException("会计或申报期间无效");result.add(new Fact(cik,t.getKey(),c.getKey(),u.getKey(),start,end,new BigDecimal(f.path("val").asText()),accession,form,filed,f.path("fp").asText(),f));if(result.size()>10000)throw new IllegalArgumentException("事实范围超过上限");}}}}return result;}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("SEC XBRL格式异常",e);}}
 public static BigDecimal difference(Fact current,Fact prior){if(!current.cik.equals(prior.cik)||!current.taxonomy.equals(prior.taxonomy)||!current.concept.equals(prior.concept)||!current.unit.equals(prior.unit)||!current.fiscalPeriod.equals(prior.fiscalPeriod)||!current.form.replace("/A","").equals(prior.form.replace("/A",""))||(current.start==null)!=(prior.start==null))throw new IllegalArgumentException("公司、单位或会计口径不可比较");if(current.start!=null&&Math.abs(java.time.temporal.ChronoUnit.DAYS.between(current.start,current.end)-java.time.temporal.ChronoUnit.DAYS.between(prior.start,prior.end))>7)throw new IllegalArgumentException("会计期间长度不可比较");return current.value.subtract(prior.value);}
}
